import{patchPackageJson}from"./package-json.js";import{readFile}from"node:fs/promises";import{join}from"node:path";async function ensurePackageDependencies(e){let t=join(e.projectRoot,`package.json`),n;try{n=JSON.parse(await readFile(t,`utf8`))}catch(e){if(e.code===`ENOENT`)return[];throw e}let r=isRecord(n)&&isRecord(n.dependencies)?n.dependencies:{},i=Object.fromEntries(Object.entries(e.dependencies).filter(([e,t])=>r[e]!==t)),a=Object.keys(i);return a.length===0?[]:(await patchPackageJson(t,{dependencies:i}),[{dependencies:a,devDependencies:[],path:t,scripts:[]}])}function isRecord(e){return typeof e==`object`&&!!e&&!Array.isArray(e)}export{ensurePackageDependencies};